const ARTICLES = [
  {id:1, cat:"delhii", title:"Иран Бахрейн дахь АНУ-ын баазад зургаан дрон илгээж, хоёр дахь удаагаа довтоллоо", titleEn:"Iran sends six drones at US base in Bahrain in second attack in three days", time:"15 мин", timeEn:"15 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Manama%20Bahrain%20Bay%2001.jpg?width=1000", text:"Ираны Исламын хувьсгалын хамгаалалтын корпус ням гараг буюу арваннэгдүгээр сарын 15-ны үүрээр Бахрейн дахь АНУ-ын цэргийн баазын радарын системийг онилж, зургаан дрон илгээснээ мэдэгдлээ. Бахрейны нийслэл Манамад үүрийн 4 цагийн орчимд дэлбэрэлтийн дуу сонсогдож, агаарын довтолгооноос сэрэмжлүүлэх дохио дуугарсан байна. Ираны тал уг ажиллагааг АНУ-ын дайсагнасан үйлдлийн хариу гэж мэдэгджээ.\n\nБахрейны армийн мэдээлснээр тус улсын агаарын довтолгооноос хамгаалах систем Ираны хэд хэдэн агаарын довтолгоог онилсон байдаа хүрэхээс нь өмнө таслан зогсоосон байна. Бахрейны Дотоод хэргийн яам иргэддээ тайван байж, хамгийн ойрын аюулгүй газар руу шилжихийг уриалсан хоёр удаагийн сэрэмжлүүлэг гаргасан байна. Ням гарагийн довтолгоонд хохирол, хүний амь нас эрсэдсэн тухай одоогоор батлагдсан мэдээлэл гараагүй байна.\n\nЭнэ нь Бахрейн руу гурван хоногийн дотор хийсэн хоёр дахь довтолгоо болж байна. Баасан гарагт буюу арваннэгдүгээр сарын 13-нд Хувьсгалын хамгаалалтын корпус Бахрейн дахь АНУ-ын эрт сэрэмжлүүлэх радарын системийг онилсон гэж мэдэгдсэн бол АНУ-ын Төв командлал Ираны хоёр дроныг буудаж унагасан, хохирол гараагүй гэж мэдэгдсэн юм. Бахрейн нь АНУ-ын Тэнгисийн 5-р флотын бааз байрладаг улс бөгөөд АНУ, Израилийн Иран руу хийсэн гэнэтийн довтолгоогоор хоёрдугаар сарын 28-нд эхэлсэн дайны туршид Ираны мянга мянган дрон, пуужингийн довтолгоонд өртөж иржээ.\n\nИраны тал Хормузын хоолойг хаасан гэж мэдэгдэж, АНУ-ын аливаа түрэмгийллийг улам ширүүн хариулах болно гэж анхааруулсан байна. Арабын Нэгдсэн Эмират Улс Ираны довтолгоог эрс буруушаажээ. Энхийн хэлэлцээ зогсонги байдалд орсон үед хоёр сар орчим үргэлжилсэн харьцангуй нам гүм үе дуусч, Персийн булангийн бүс нутагт хурцадмал байдал дахин нэмэгдэж байна.", textEn:"Iran's Islamic Revolutionary Guard Corps said it sent six drones at a US military base's radar system in Bahrain in the early hours of Sunday, November 15. Explosions were heard in the Bahraini capital Manama at around 4 a.m. as air-raid sirens sounded. The Iranian side described the operation as a response to hostile US actions.\n\nBahrain's military said its air defence systems intercepted several Iranian aerial attacks before they reached their targets. The Interior Ministry issued two alerts urging residents to stay calm and move to the nearest safe location. No confirmed reports of damage or casualties from Sunday's attack had emerged.\n\nThis was the second attack on Bahrain in three days. On Friday, November 13, the Revolutionary Guards said they had targeted a US early-warning radar system in Bahrain, while US Central Command said it had shot down two Iranian drones with no damage. Bahrain hosts the US Navy's 5th Fleet and has faced thousands of Iranian drone and missile strikes since the war that began on February 28 with surprise US-Israeli attacks on Iran.\n\nIran said the Strait of Hormuz was closed and warned that any American aggression would be met with an even harsher response. The United Arab Emirates strongly condemned the Iranian attack. With peace talks stalled, a roughly two-month lull has ended and tensions across the Gulf are rising again."},
  {id:2, cat:"uls-tor", title:"Оюутолгойн ашгаас иргэн бүрд 857 мянган төгрөг шилжүүлэх эсэхийг УИХ-ын байнгын хороод хэлэлцэнэ", titleEn:"Parliamentary committees to discuss paying 857,000 tugriks per citizen from Oyu Tolgoi profits", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Oyu%20Tolgoi%2007.JPG?width=760", text:"Улсын Их Хурлын Эдийн засгийн байнгын хороо болон Өргөдлийн байнгын хорооны хамтарсан хуралдаан ирэх мягмар гараг буюу арваннэгдүгээр сарын 17-ны 14:00 цагт зарлагджээ. Хамтарсан хуралдаанаар иргэдээс гаргасан өргөдлийг хэлэлцэх бөгөөд Оюутолгойн ногдол ашиг болох гурван их наяд төгрөгөөс иргэн бүрд 857,000 төгрөгийг хувь дансанд нь шилжүүлж өгөх асуудлаар хуулийн төсөл санаачлах тухай асуудлыг хэлэлцэх юм.\n\nЗасгийн газар ирэх онд Оюутолгой төслөөс гурван их наяд төгрөг авахаар хөрөнгө оруулагч талтай тохирсон болохоо мэдэгдсэн байна. Иргэдийн өргөдөл нь энэхүү ногдол ашгийг иргэдэд шууд хуваарилахыг шаардаж байгаа бөгөөд байнгын хороод өргөдлийг хэлэлцэж, хуулийн төсөл санаачлах эсэхийг шийдэх юм. Оюутолгой нь Монголын хамгийн том зэс, алтны уурхай бөгөөд түүний ашгийн хуваарилалт олон жилийн турш нийгмийн анхаарлын төвд байгаа асуудал юм.\n\nХамтарсан хуралдааны шийдвэр нь ногдол ашгийг хэрхэн зарцуулах талаарх маргаанд чухал ач холбогдолтой болох төлөвтэй байна. Засгийн газрын зүгээс ногдол ашгийг төсөвт төвлөрүүлж, хөгжлийн төслүүдэд зарцуулах байр суурьтай байгаа бол иргэдийн өргөдөл нь мөнгийг иргэн бүрд шууд олгохыг шаардаж байна. Хуралдааны үр дүнг олон нийт анхааралтай ажиглаж байна.", textEn:"A joint session of the State Great Khural's Standing Committee on Economy and Standing Committee on Petitions has been scheduled for Tuesday, November 17, at 2 p.m. The joint session will discuss a citizens' petition on initiating a bill to transfer 857,000 tugriks to each citizen's personal account from the three trillion tugriks of Oyu Tolgoi dividends.\n\nThe Government has said it agreed with the investors to receive three trillion tugriks from the Oyu Tolgoi project next year. The citizens' petition demands that this dividend be distributed directly to the people, and the committees will discuss the petition and decide whether to initiate a bill. Oyu Tolgoi is Mongolia's largest copper and gold mine, and the distribution of its profits has been a matter of public debate for many years.\n\nThe joint session's decision is expected to be significant for the dispute over how the dividend should be spent. The Government's position is to channel the dividend into the budget and spend it on development projects, while the citizens' petition demands the money be paid directly to every citizen. The public is watching the outcome of the session closely."},
  {id:3, cat:"niigem", title:"2027 оноос даралт, зүрх, чихрийн шижингийн эмийг ЭМДС 100 хувь хөнгөлнө: 220 төрлийн эм жагсаалтад орно", titleEn:"From 2027, health insurance will fully cover blood pressure, heart and diabetes drugs: 220 medicines on the list", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/The%20Medicine%20Box%20pharmacy.jpg?width=760", text:"2027 оны нэгдүгээр сарын 1-нээс ахмад настан болон зорилтот бүлгийн иргэдийн өдөр тутам хэрэглэдэг даралт бууруулах, зүрх судас, чихрийн шижингийн эмийн төлбөрийг Эрүүл мэндийн даатгалын сан 100 хувь хөнгөлнө гэж мэдээллээ. Засгийн газар энэ шийдвэрийг 2027 оны улсын төсвийн хүрээнд зарлаж, хөнгөлөлттэй эмийн жагсаалтыг шинэчилсэн байна.\n\nЭрүүл мэндийн яам шинэчилсэн жагсаалтад зорилтот бүлэгт шаардлагатай 220 төрлийн эмийг багтаахаар тусгасан бөгөөд ингэснээр иргэдийн халааснаас гарах 103 тэрбум төгрөгийн зардлыг хэмнэнэ гэж тооцжээ. Хөнгөлөлтөд ахмад настан, хүүхэд, хөгжлийн бэрхшээлтэй иргэд зэрэг зорилтот бүлэг хамрагдана. Архаг өвчтэй иргэдийн хувьд өдөр тутам хэрэглэдэг эмийн зардал нь өрхийн төсөвт хүнд дарамт болдог байсан тул энэ шийдвэр нь тэдний амьжиргаанд шууд нөлөөлөх төлөвтэй байна.\n\nЭмийн жагсаалт болон хөнгөлөлттэй үнээр эм олгох эмийн сангийн байршлыг Эрүүл мэндийн даатгалын ерөнхий газрын цахим хуудас болон 1800-1363 дугаарын утсаар лавлах боломжтой. Шинэ журам хэрэгжиж эхлэхтэй холбогдуулан эмийн хангамж, эмийн сангуудын бэлтгэлийг хангах ажил үргэлжилж байна.", textEn:"From January 1, 2027, the Health Insurance Fund will cover 100 percent of the cost of blood pressure, cardiovascular and diabetes medicines used daily by elderly people and target groups. The Government announced the decision as part of the 2027 state budget and updated the list of discounted medicines.\n\nThe Ministry of Health has included 220 types of medicines needed by target groups in the updated list, which is expected to save citizens 103 billion tugriks in out-of-pocket costs. The relief covers target groups including the elderly, children and people with disabilities. For people with chronic illnesses, the cost of daily medicines has been a heavy burden on household budgets, so the decision is expected to have a direct effect on their livelihoods.\n\nThe list of medicines and the locations of pharmacies that dispense them at discounted prices can be found on the website of the General Authority for Health Insurance or by calling 1800-1363. Work is under way to ensure medicine supplies and pharmacy readiness as the new rules take effect."},
  {id:4, cat:"niigem", title:"Цаг агаарын аюултай үзэгдлээс сэрэмжлүүлж байна: өнөөдөр, маргааш ихэнх нутгаар цасан шуурга шуурна", titleEn:"Dangerous weather warning: blizzards expected across most of the country today and tomorrow", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Babia%20G%C3%B3ra%2C%2020230304%200651%203162.jpg?width=760", text:"Цаг уур, орчны шинжилгээний газраас цаг агаарын аюултай үзэгдлээс сэрэмжлүүлэх мэдээ гаргажээ. Арваннэгдүгээр сарын 16-нд Говь-Алтай, Баянхонгорын хойд хэсгээр, 16-17-нд шилжих шөнө Өвөрхангай, Дундговийн нутаг, Өмнөговийн хойд, Төв аймгийн өмнөд хэсгээр, 17-ны өдөр Төв аймгийн өмнөд, Дорнод, Сүхбаатарын баруун, Дундговь, Дорноговь, Хэнтийн нутгаар цасан шуурга шуурна.\n\nАрваннэгдүгээр сарын 16-нд баруун аймгуудын нутгийн зүүн хэсэг, төв болон говийн аймгуудын ихэнх нутгаар, 17-нд нутгийн зүүн хагаст цас орж, цасан шуурга шуурч, ихэнх нутгаар хүйтэрнэ. Зам, даваа, гүвээнд үзэгдэх орчин хязгаарлагдаж, халтиргаа гулгаа, мөстөлт үүсэхийг малчид, иргэд, тээвэрчдэд анхааруулж байна. Салхи говь, тал, хээрийн нутгаар секундэд 15-17 метр хүрч ширүүсэх төлөвтэй байна.\n\nУлаанбаатар хот орчмоор өнөөдөр үүлэрхэг, шөнөдөө ялимгүй цас, өдөртөө цас орно. Салхи баруун өмнөөс секундэд 5-10 метр, шөнөдөө Яармаг-Сонгины орчмоор 16-18 хэм, бусад хэсгээр 11-13 хэм, өдөртөө 6-8 хэм хүйтэн байна. Багануур орчмоор шөнөдөө 19-21 хэм, өдөртөө 9-11 хэм хүйтэн байх төлөвтэй байна. Арваннэгдүгээр сарын 17-ноос 21-нийг хүртэлх төлөвөөр цас үргэлжлэн орох төлөвтэй байна.", textEn:"The National Agency for Meteorology and Environmental Monitoring has issued a warning about dangerous weather. On November 16, blizzards are expected in Govi-Altai and northern Bayankhongor; on the night of November 16-17 in Uvurkhangai, Dundgovi, northern Umnugovi and southern Tuv; and on November 17 in southern Tuv, Dornod, western Sukhbaatar, Dundgovi, Dornogovi and Khentii.\n\nOn November 16, snow will fall in the eastern parts of the western aimags and most of the central and Gobi aimags, and on November 17 in the eastern half of the country, with blizzards and colder temperatures across most areas. Herders, residents and drivers are warned that visibility will be limited on roads, passes and hills, with slippery conditions and icing. Winds will strengthen to 15-17 metres per second across the Gobi, steppe and field regions.\n\nAround Ulaanbaatar today it will be cloudy, with slight snow overnight and snow during the day. Winds from the southwest at 5-10 metres per second; overnight minus 11-13 degrees, minus 16-18 in the Yaarmag-Songino area, and minus 6-8 during the day. Around Baganuur, overnight minus 19-21 degrees and minus 9-11 during the day. The outlook for November 17-21 shows snow continuing."},
  {id:5, cat:"edi-zasag", title:"Ерөнхий сайд Н.Учрал: нөөцийн мах бэлтгэн нийлүүлэх тогтолцоог үндсээр нь шинэчилж байна", titleEn:"PM N. Uchral: reserve meat supply system is being fundamentally renewed", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Meat%20market%20at%20New%20Market%2C%20Kolkata%2001.jpg?width=760", text:"Ерөнхий сайд Н.Учрал нөөц бүрдүүлэлтийн ажлын явцыг шалгаж, арваннэгдүгээр сарын 14-нд “Дельтафүүдс”, “Дөмөг хүнс” компанид ажиллалаа. Хүн амын өвөл, хаврын улирлын хэрэгцээнд шаардагдах гол нэрийн хүнсний бүтээгдэхүүний хангамж, нийлүүлэлтийн тогтвортой байдлыг хангаж, хомсдол болон үнийн өсөлтөөс сэргийлэх зорилгоор 12,000 тонн төмс, хүнсний ногоо, 15-20 мянган тонн мах нөөцлөх шийдвэрийг Засгийн газар гаргасан байна.\n\nӨнөөдрийн байдлаар 80 гаруй аж ахуйн нэгж, ногоочдоос 11,130 тонн төмс, хүнсний ногоо төвлөрүүлэн нөөц бүрдүүлэлт 92.8 хувьтай байгаа бол 3,091 тонн мах нөөцлөөд байна. Ерөнхий сайд нийслэлийн хүн амын хэрэгцээнд зориулсан нөөцийн мах бэлтгэн нийлүүлэх тогтолцоог үндсээр нь шинэчилж байгааг онцлоод, ийн нөөцөлж байгаа нь өвөл, хаврын улиралд хомсдол үүсэх, үнийн огцом өсөлт бий болохоос урьдчилан сэргийлэхээс гадна малчид, тариаланчид, аж ахуйн нэгжүүдээ дэмжиж байгаа ажил юм гэлээ.\n\n2026 оны улсын төсвийн тодотголд 120 тэрбум төгрөг суулгаж, стратегийн болон гол нэрийн хүнсний бүтээгдэхүүнийг төрөөс худалдан авч нөөц бүрдүүлэхээр шийдвэрлэсэн байна. Өнөөдрийн байдлаар арилжааны банкнаас 13 аж ахуйн нэгжид нийт 86.7 тэрбум төгрөгийн хөнгөлөлттэй санхүүжилт батлагдаж, мах бэлтгэх хяналтын гэрээ байгуулжээ. Ерөнхий сайд нөөцийн махыг хугацаанд нь бэлтгэх, чанар, гарал үүслийг нь нягт хянах, иргэдэд найдвартай нийлүүлэх үүргийг салбарын яам, нийслэлийн удирдлагуудад өгсөн байна.", textEn:"Prime Minister N. Uchral inspected the progress of reserve stockpiling and visited Deltafoods and Domog Khuns companies on November 14. The Government decided to stockpile 12,000 tonnes of potatoes and vegetables and 15,000-20,000 tonnes of meat to ensure stable supplies of staple foods for the winter and spring, and to prevent shortages and price rises.\n\nSo far, 11,130 tonnes of potatoes and vegetables have been collected from more than 80 enterprises and growers, bringing stockpiling to 92.8 percent, while 3,091 tonnes of meat have been reserved. The Prime Minister stressed that the system for preparing and supplying reserve meat for the capital's population is being fundamentally renewed, noting that stockpiling prevents winter and spring shortages and sharp price rises while supporting herders, farmers and businesses.\n\nThe amended 2026 state budget allocated 120 billion tugriks for the state to purchase and stockpile strategic and staple foods. To date, commercial banks have approved 86.7 billion tugriks in concessional financing for 13 enterprises, with meat supply monitoring contracts signed. The Prime Minister instructed the relevant ministry and city authorities to prepare reserve meat on time, strictly monitor its quality and origin, and deliver it reliably to residents."},
  {id:6, cat:"edi-zasag", title:"Эгийн голын УЦС-ын төсөл байгаль орчинд сөрөг нөлөөгүй гэсэн урьдчилсан дүгнэлт гарлаа", titleEn:"Preliminary finding: Eg River hydropower project has no negative environmental impact", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/ThreeGorgesDam-China2009.jpg?width=760", text:"Монгол, Оросын хамтарсан судалгаагаар Эгийн голын усан цахилгаан станцын төсөл байгаль орчинд сөрөг нөлөөгүй гэсэн урьдчилсан дүгнэлт гарсан тухай мэдээллээ. Эгийн голын УЦС-ын төсөл нь олон жилийн турш хэлэлцэгдэж ирсэн бөгөөд түүний байгаль орчинд үзүүлэх нөлөө нь хөрш орнуудын анхаарлыг татаж байсан юм.\n\nЭгийн гол нь Сэлэнгэ мөрөнд цутгаж, цаашлаад Байгаль нуурт хүрдэг тул төслийн байгаль орчны үнэлгээ онцгой анхаарал татдаг. Оросын тал өмнө нь Байгаль нуурын экосистемд үзүүлж болзошгүй нөлөөний талаар санаа зовниж байгаагаа илэрхийлж байсан юм. Хоёр улсын хамтарсан судалгаа нь эдгээр асуудлыг шинжлэх ухааны үндэстэйгээр шийдвэрлэх зорилготой хийгдсэн байна.\n\nУрьдчилсан дүгнэлт нь төслийн байгаль орчны үнэлгээний эхний шат бөгөөд эцсийн шийдвэр гарахаас өмнө нэмэлт судалгаа, хэлэлцүүлэг шаардлагатай хэвээр байна. Эгийн голын УЦС нь Монголын эрчим хүчний хангамжийг нэмэгдүүлэх, сэргээгдэх эрчим хүчний эзлэх хувийг өсгөхөд чухал үүрэг гүйцэтгэх боломжтой гэж үзэж байна.", textEn:"A joint Mongolian-Russian study has reached the preliminary conclusion that the Eg River hydropower project has no negative impact on the environment. The Eg River hydropower project has been discussed for many years, and its environmental impact has drawn the attention of neighbouring countries.\n\nBecause the Eg River flows into the Selenge River and onward to Lake Baikal, the project's environmental assessment has attracted particular attention. The Russian side had previously expressed concern about possible effects on the Baikal ecosystem. The joint study by the two countries was carried out to address these issues on a scientific basis.\n\nThe preliminary conclusion is the first stage of the project's environmental assessment, and further research and discussion are still needed before a final decision. The Eg River hydropower plant could play an important role in increasing Mongolia's energy supply and raising the share of renewable energy."},
  {id:7, cat:"delhii", title:"Трамп, Ши Жиньпин, Путин нар арваннэгдүгээр сарын 19-нд Шэньжэньд түүхэн гурвалсан уулзалт хийнэ", titleEn:"Trump, Xi and Putin to hold historic trilateral meeting in Shenzhen on November 19", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline%20in%20Shenzhen%20%2820250327%29.jpg?width=760", text:"АНУ-ын Ерөнхийлөгч Дональд Трамп, Хятадын дарга Ши Жиньпин, Оросын Ерөнхийлөгч Владимир Путин нар арваннэгдүгээр сарын 19-нд Хятадын Шэньжэнь хотод анх удаа гурвалсан уулзалт хийхээр болсон тухай Цагаан ордон арваннэгдүгээр сарын 13-нд баталгаажууллаа. Уулзалт нь Ази, Номхон далайн эдийн засгийн хамтын ажиллагааны дээд хэмжээний уулзалтын хүрээнд болох бөгөөд дэлхийн хамгийн том цөмийн гурван гүрний удирдагчид анх удаа гурвуулаа нэгэн зэрэг уулзаж байгаа нь энэ юм.\n\nУулзалтын гол сэдэв нь цөмийн зэвсгийн тоог бууруулах болон Ирантай холбоотой дайн байх болно. Цагаан ордны хэвлэлийн төлөөлөгч Оливия Уэйлс Трампын хувьд дэлхийн цөмийн зэвсгийг бууруулах асуудлыг хэлэлцэх нь тодорхой байгаа бөгөөд энэ тархалт маш аюултай гэж Ерөнхийлөгч үзэж байгааг мэдэгджээ. Харин Оросын Украин руу хийсэн довтолгоог хэлэлцэхээр төлөвлөөгүй байна.\n\nАНУ-ын өндөр албан тушаалтан уулзалтаас ямар нэгэн тохиролцоонд хүрнэ гэж хүлээхгүй байгаагаа мэдэгдсэн байна. АНУ, Оросын хоорондын сүүлчийн цөмийн зэвсгийн хяналтын гэрээ болох Шинэ START гэрээ энэ оны хоёрдугаар сард хугацаа нь дууссан бөгөөд түүнээс хойш хоёр том цөмийн гүрний зэвсэгт ямар ч хязгаар тогтоогдоогүй байна. Стокгольмын олон улсын энх тайвны судалгааны хүрээлэнгийн 2026 оны тооцоогоор АНУ 5,042, Орос 5,420, Хятад 620 цөмийн цэнэгт хошуутай байна. Хятадын тал хэлэлцээнд оролцохыг шаардах нь шударга ч биш, оновчтой ч биш гэж мэдэгдсэн байна.", textEn:"US President Donald Trump, Chinese President Xi Jinping and Russian President Vladimir Putin will hold their first-ever trilateral meeting on November 19 in Shenzhen, China, the White House confirmed on November 13. The meeting will take place on the sidelines of the Asia-Pacific Economic Cooperation summit, the first time the leaders of the world's three largest nuclear powers have met together.\n\nThe main topics will be reducing nuclear weapons and the war involving Iran. White House spokeswoman Olivia Wales said Trump had made clear he would discuss reducing the world's nuclear weapons, which the President views as a very dangerous proliferation. Russia's war in Ukraine is not expected to be discussed.\n\nA senior US official said Washington does not expect to reach any agreement at the meeting. The last nuclear arms control treaty between the US and Russia, New START, expired in February this year, leaving the two largest arsenals without agreed caps for the first time in more than half a century. According to the Stockholm International Peace Research Institute's 2026 estimates, the US holds 5,042 nuclear warheads, Russia 5,420 and China 620. China has said it is neither fair nor reasonable to ask it to join the talks."},
  {id:8, cat:"delhii", title:"Израиль 10 дугаар сарын 7-ны довтолгоог төлөвлөсөн Хамасын ахлах командлагчийг устгав", titleEn:"Israel kills senior Hamas commander who planned the October 7 attack", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Damage%20in%20Gaza%20Strip%20during%20the%20October%202023%20-%2029.jpg?width=760", text:"Хамасын Рафах бригадын командлагч Самир Абу Юнис Израилын цохилтод амиа алдсан тухай Израилын арми болон Хамасын цэргийн жигүүр ням гарагт баталгаажууллаа. Израилын арми болон Шин Бет аюулгүй байдлын алба бямба гарагаас ням гарагт шилжих шөнө Газын зурвасын өмнөд хэсэг дэх Хан Юнисын Аль-Маваси дүүрэгт гудамжаар явж байсан командлагчийг онилсон байна.\n\nХамасын Аль-Кассам бригадын мэдэгдлээр Абу Юнис нь 2023 оны аравдугаар сарын 7-ны довтолгоог төлөвлөж, удирдан явуулсан гол командлагчдын нэг байсан байна. Тэрбээр 1991 онд Аль-Кассам бригадад элссэн ахмад командлагч бөгөөд хоёр сарын өмнө буюу есдүгээр сарын 15-нд өмнөх командлагч Наэл Абу Обейд Израилын цохилтод амиа алдсаны дараа Рафах бригадын командлагчаар томилогдсон юм. Газын иргэний хамгааллын төлөөлөгчийн мэдээлснээр Абу Юнис 53 настай байсан бөгөөд цохилтод хоёр хүн шархадсан байна.\n\nЭнэ цохилт нь өнгөрсөн пүрэв гарагт Израилын арми Хан Юнисын бригадын командлагч Мухаммад Абу Исмаилыг онилж, Хан Юнисын Нассер эмнэлгийн цогцолборт цохилт өгсний дараа болсон бөгөөд Абу Исмаил амиа алдсан эсэх нь хараахан батлагдаагүй байна. Хоёр жилийн дайны дараа 2025 оны аравдугаар сард хэрэгжиж эхэлсэн гал зогсоох хэлэлцээрийг зөрчсөн гэж Израиль, Хамас хоёр бие биенээ буруутгаж байна.", textEn:"Hamas's Rafah Brigade commander Samir Abu Younis was killed in an Israeli strike, the Israeli military and Hamas's military wing confirmed on Sunday. The Israeli military and the Shin Bet security agency struck the commander as he walked down a street in the Al-Mawasi district of Khan Younis in southern Gaza overnight from Saturday to Sunday.\n\nAccording to Hamas's Al-Qassam Brigades, Abu Younis was one of the key commanders who planned and oversaw the October 7, 2023 attack. The veteran commander joined the Al-Qassam Brigades in 1991 and was appointed commander of the Rafah Brigade two months ago, after the previous commander, Nael Abu Obeid, was killed in an Israeli strike on September 15. Gaza's civil defence said Abu Younis was 53 and two people were wounded in the strike.\n\nThe strike came after the Israeli military targeted Khan Younis Brigade commander Muhammad Abu Ismail at the Nasser Hospital complex in Khan Younis on Thursday; it is not yet confirmed whether Abu Ismail was killed. Israel and Hamas accuse each other of violating the ceasefire that took effect in October 2025 after two years of war."},
  {id:9, cat:"delhii", title:"АСЕАН-ы дээд хэмжээний уулзалт Филиппинд эхэллээ: дэлхийн удирдагчид Манилад цугларав", titleEn:"ASEAN summit opens in the Philippines as world leaders gather in Manila", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Skyline%20in%20Manila%2017.jpg?width=760", text:"Зүүн Өмнөд Азийн орнуудын холбоо буюу АСЕАН-ы дээд хэмжээний уулзалт Филиппинд өнөөдөр буюу арваннэгдүгээр сарын 16-нд эхэлж, маргааш хүртэл үргэлжилнэ. Дэлхийн удирдагчид уулзалтад оролцохоор арваннэгдүгээр сарын 15-нд Манилад цугларч эхэлсэн байна. Энэ удаагийн дээд хэмжээний уулзалт нь бүс нутгийн хамтын ажиллагаа, худалдаа, аюулгүй байдлын асуудлыг хэлэлцэх чухал талбар болж байна.\n\nЭнэтхэгийн Ерөнхий сайд Нарендра Моди арваннэгдүгээр сарын 16-17-нд болох АСЕАН-ы дээд хэмжээний уулзалтад оролцож байна. Модигийн оролцоо нь Энэтхэг, Зүүн Өмнөд Азийн харилцааг бэхжүүлэхэд чухал ач холбогдолтой гэж үзэж байна. Уулзалтын үеэр бүс нутгийн худалдаа, хөрөнгө оруулалт, дижитал эдийн засаг болон далайн аюулгүй байдлын асуудлыг хэлэлцэх төлөвтэй байна.\n\nФилиппин улс энэ удаагийн дээд хэмжээний уулзалтыг зохион байгуулж байгаа бөгөөд Манила хотод аюулгүй байдлын арга хэмжээг чангатгажээ. Уулзалтад АСЕАН-ы гишүүн орнуудын удирдагчид болон түнш орнуудын төлөөлөгчид оролцоно. АСЕАН нь Зүүн Өмнөд Азийн 10 орныг нэгтгэсэн бүс нутгийн байгууллага бөгөөд дэлхийн эдийн засаг, улс төрд нөлөө нь өссөөр байна. Дээд хэмжээний уулзалтын үр дүн нь бүс нутгийн худалдааны хэлэлцээр, цаг уурын өөрчлөлтийн эсрэг хамтын ажиллагаа болон Өмнөд Хятадын тэнгисийн маргааны асуудалд хэрхэн нөлөөлөх нь олон улсын анхаарлыг татаж байна.", textEn:"The summit of the Association of Southeast Asian Nations, ASEAN, opens in the Philippines today, November 16, and continues through tomorrow. World leaders began gathering in Manila on November 15 to take part. This year's summit is an important forum for discussing regional cooperation, trade and security.\n\nIndian Prime Minister Narendra Modi is attending the ASEAN summit on November 16-17. Modi's participation is seen as important for strengthening ties between India and Southeast Asia. The summit is expected to discuss regional trade, investment, the digital economy and maritime security.\n\nThe Philippines is hosting this year's summit, and security measures have been tightened in Manila. Leaders of ASEAN member states and representatives of partner countries will attend. ASEAN brings together 10 Southeast Asian nations, and its influence in the global economy and politics continues to grow. The outcome of the summit will be closely watched for its impact on regional trade agreements, joint action against climate change, and the South China Sea disputes."},
  {id:10, cat:"delhii", title:"Итали Мета компанид хэрэглэгчдийн зурагт зөвшөөрөлгүй хандсан гэж 805 сая еврогийн торгууль ногдууллаа", titleEn:"Italy fines Meta 805 million euros over accessing users' photos without consent", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Aerial%20view%20of%20Facebook%20campus%20in%20Menlo%20Park%2C%20September%202019.JPG?width=760", text:"Италийн мэдээлэл хамгаалах байгууллага Мета компанид 805 сая еврогийн торгууль ногдуулсан тухай мэдээллээ. Торгуулийн шалтгаан нь Мета компани Фэйсбүүкээр дамжуулан Андройд хэрэглэгчдийн зураг, видеонд тэдний мэдээлэлтэй зөвшөөрөлгүйгээр хандсан явдал гэж Италийн мэдээлэл хамгаалах байгууллага үзжээ.\n\n805 сая евро буюу 887 сая ам.доллар орчим хэмжээний торгууль нь Европын Холбооны мэдээлэл хамгаалах дүрмийн хүрээнд ногдуулсан хамгийн том торгуулиудын нэг болж байна. Европын Холбооны мэдээлэл хамгаалах ерөнхий журам буюу GDPR нь компаниудад хэрэглэгчдийн хувийн мэдээлэлд хандахын өмнө тэдний тодорхой, мэдээлэлтэй зөвшөөрлийг авахыг шаарддаг.\n\nМета компани нь Фэйсбүүк, Инстаграм, Ватсапп зэрэг дэлхийн хамгийн том сошиал сүлжээнүүдийг эзэмшдэг бөгөөд хэрэглэгчдийн мэдээллийг хэрхэн ашигладаг нь олон жилийн турш зохицуулагчдын анхаарлын төвд байсаар иржээ. Торгуулийн шийдвэр нь технологийн томоохон компаниудын мэдээлэл ашиглах практикт Европын зохицуулагчид улам хатуу хандаж байгааг харуулж байна.", textEn:"Italy's data protection authority has fined Meta 805 million euros. The authority found that Meta accessed Android users' photos and videos through Facebook without their informed consent.\n\nThe fine of 805 million euros, around 887 million US dollars, is one of the largest imposed under the European Union's data protection rules. The EU's General Data Protection Regulation, GDPR, requires companies to obtain users' clear and informed consent before accessing their personal data.\n\nMeta owns some of the world's largest social networks, including Facebook, Instagram and WhatsApp, and how it uses user data has been under regulators' scrutiny for years. The fine shows European regulators taking an increasingly strict approach to the data practices of large technology companies."},
  {id:11, cat:"delhii", title:"Саудын Араб Эр-Рияд руу чиглэсэн Хусигийн хоёр пуужин, гурван дроныг таслан зогсоолоо", titleEn:"Saudi Arabia intercepts two Houthi missiles and three drones targeting Riyadh", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Riyadh%20Skyline.jpg?width=760", text:"Саудын Арабын тэргүүлсэн эвсэл Йемений Хуси босогчдын Эр-Рияд руу чиглүүлсэн хоёр пуужин, гурван дроныг таслан зогсоосон тухай мэдээллээ. Довтолгоо нь Ираны Хувьсгалын хамгаалалтын корпус Бахрейн дахь АНУ-ын баазад дрон довтолгоо хийснээ мэдэгдсэн тэр өдөр болсон бөгөөд бүс нутгийн хурцадмал байдал нэмэгдэж байгааг харуулж байна.\n\nХуси босогчид Йемений ихэнх нутгийг хянадаг бөгөөд бүс нутгийн дайны туршид Саудын Араб болон түүний холбоотнууд руу пуужин, дроноор удаа дараа довтолж иржээ. Саудын Арабын агаарын довтолгооноос хамгаалах систем довтолгоог нийслэлд хүрэхээс нь өмнө таслан зогсоосон байна. Довтолгоонд хохирол, хүний амь нас эрсэдсэн тухай мэдээлэл гараагүй байна.\n\nЭнэ үйл явдал нь АНУ, Израилийн Иран руу хийсэн довтолгоогоор эхэлсэн дайн Персийн булангийн бүс нутаг даяар өргөжиж байгааг харуулж байна. Хуси босогчид Ираны дэмжлэгтэй гэж үздэг бөгөөд тэдний довтолгоо нь Ираны Бахрейн руу хийсэн довтолгоотой зэрэгцэн өрнөж, бүс нутгийн аюулгүй байдалд ноцтой сорилт болж байна.", textEn:"The Saudi-led alliance said it intercepted two Houthi missiles and three drones targeting Riyadh. The attack came on the same day Iran's Revolutionary Guard Corps said it had carried out a drone attack on a US base in Bahrain, showing rising regional tensions.\n\nThe Houthi rebels control most of Yemen and have repeatedly attacked Saudi Arabia and its allies with missiles and drones during the regional war. Saudi air defence systems stopped the attack before it reached the capital. No reports of damage or casualties have emerged.\n\nThe incident shows the war that began with US and Israeli attacks on Iran spreading across the Gulf region. The Houthis are seen as backed by Iran, and their attack, coinciding with Iran's attack on Bahrain, poses a serious challenge to regional security."},
  {id:12, cat:"tech", title:"Нвидиагийн гүйцэтгэх захирал Женсен Хуан 33 жил удирдсаныхаа дараа огцорлоо", titleEn:"Nvidia CEO Jensen Huang resigns after 33 years at the helm", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/GPU%20NVIDIA%20NV45%20ES%20GPU.jpg?width=760", text:"Дэлхийн хамгийн том технологийн компаниудын нэг болох Нвидиагийн гүйцэтгэх захирал Женсен Хуан арваннэгдүгээр сарын 12-нд албан тушаалаасаа огцорчээ. Тэрбээр 1993 онд үүсгэн байгуулсан компаниа 33 жилийн турш удирдаж, хиймэл оюуны хувьсгалын гол хөдөлгөгч хүч болгон хөгжүүлсэн юм. Төлөөлөн удирдах зөвлөлөөс санхүүгийн захирал Колетт Крессийг түр гүйцэтгэх захирлаар томилсон байна.\n\nХуаны огцролт нь хоёр гэр бүлээс гадуурх харилцаа илчлэгдсэний дараа болсон бөгөөд тэдгээрийн нэг нь Хятадын тагнуул гэж АНУ-ын тагнуулын байгууллагууд сэжиглэж буй Сингапурт суугаа технологийн гүйцэтгэх захиралтай холбоотой байв. Арваннэгдүгээр сарын 8-нд Хуан гэр бүлээсээ гадуур харилцаатай байснаа хүлээн зөвшөөрч, Нвидиагийн зөвлөл түүнийг гадаадын тагнуулын ажиллагааны бай болсон эсэхийг шалгах бие даасан мөрдөн шалгалт эхлүүлсэн юм. Арваннэгдүгээр сарын 11-нд Нью-Йорк Таймс сонин Хуан мөн компанийн эрүүл мэндийн асуудал хариуцсан дэд ерөнхийлөгч Кимберли Пауэллтай харилцаатай байсан гэж мэдээлсэн байна.\n\nОгцролтын мэдээний дараа Нвидиагийн хувьцаа нэг өдрийн дотор 14 хүртэл хувиар унаж, амралтын өдрөөс хойш компанийн зах зээлийн үнэлгээнээс 450 тэрбум ам.доллар орчим арилсан байна. Төлөөлөн удирдах зөвлөл байнгын залгамжлагчийг дотоод болон гадаад нэр дэвшигчдээс хайж байгаа бөгөөд Эпл компанийн техник хангамжийн захирал Жонни Сроужи, Нвидиагийн технологийн захирал Майкл Каган нарын нэр дурдагдаж байна. Ирэх долоо хоногийн орлогын тайлан нь компанийн түүхэн дэх хамгийн чухал тайлан болох төлөвтэй байна.", textEn:"Jensen Huang, CEO of Nvidia, one of the world's largest technology companies, resigned on November 12. He led the company he co-founded in 1993 for 33 years, building it into the main driving force of the artificial intelligence revolution. The board appointed Chief Financial Officer Colette Kress as interim CEO.\n\nHuang's resignation came after revelations of two extramarital affairs, one involving a Singapore-based tech executive whom US intelligence agencies suspect of spying for China. On November 8, Huang admitted to infidelity, and Nvidia's board opened an independent investigation into whether he had been targeted by a foreign intelligence operation. On November 11, the New York Times reported that Huang had also had a relationship with Kimberly Powell, Nvidia's vice president of healthcare.\n\nAfter the resignation announcement, Nvidia shares fell as much as 14 percent in a single day, wiping around 450 billion US dollars off the company's market value since the weekend. The board is searching for a permanent successor among internal and external candidates, with names including Apple hardware chief Johny Srouji and Nvidia CTO Michael Kagan. Next week's earnings call is expected to be the most important in the company's history."},
  {id:13, cat:"tech", title:"SpaceX Starship-ийн дээд шатлалыг тойрог замаас буцаан авч, механик гараар анх удаа барьж авлаа", titleEn:"SpaceX catches Starship upper stage mid-air with mechanical arms for the first time", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/SpaceX%20Starship%20before%20IFT-5.jpg?width=760", text:"SpaceX компани Starship хөлгийн 15 дахь туршилтын нислэгийн хүрээнд тойрог замд гарсан дээд шатлалыг хөөргөх талбайд буцаан авч, механик гар буюу “chopsticks”-ээр анх удаа барьж авлаа. 124 метр өндөр пуужин арваннэгдүгээр сарын 13-ны баасан гарагт Техас мужийн Старбейс хотоос хөөрч, дээд шат нь тойрог замд гарч, 26 шинэ үеийн Starlink хиймэл дагуул амжилттай байрлуулсан байна.\n\nДээд шат буюу Ship нь дэлхийг 14 удаа тойрсны дараа хөөрснөөсөө 22 цаг хагасын дараа Старбейс рүү буцаж ирлээ. Хөөргөх цамхагийн аварга механик гарууд хөлгийг агаарт барьж авсан нь тойрог замд гарсан Starship-ийн дээд шатлалыг хөөргөх талбайд анх удаа буцаан авсан үйл явдал болж байна. Энэ нь бүрэн дахин ашиглах боломжтой пуужин бүтээх SpaceX-ийн зорилтын хувьд түүхэн ахиц юм.\n\nГэсэн хэдий ч нислэгийн хоёр шатлалыг хоёуланд нь буцаан авчрах төлөвлөгөө бүрэн биелсэнгүй. Хөөрсний дараахан Super Heavy V3 бустерт гэмтэл гарч, автомат систем нь буцаан барих оролдлогыг цуцалж, бустерийг Мексикийн булан руу чиглүүлсэн бөгөөд бустер далайд унахдаа дэлбэрсэн байна. Энэ нь V3 бустерийг цамхагт буцаан барих анхны оролдлого байв. НАСА нь Starship-ийг 2027 оны зун төлөвлөгдсөн Artemis III нислэг зэрэг сансрын нисгэгчдийг саран дээр буулгах сарны буултын хөлөг болгон хувиргахын тулд 3.2 тэрбум орчим ам.долларын санхүүжилт олгосон байна.", textEn:"SpaceX has caught the upper stage of its Starship spacecraft with the launch tower's mechanical arms, known as chopsticks, after it returned to the launch site from orbit — the first time an orbital Starship upper stage has been recovered this way. The 124-metre rocket lifted off from Starbase, Texas, on Friday, November 13, and the upper stage reached orbit and deployed 26 next-generation Starlink satellites.\n\nThe upper stage, called Ship, returned to Starbase about 22 and a half hours after liftoff, having completed 14 orbits of Earth. The giant mechanical arms of the launch tower caught the spacecraft mid-air, marking the first recovery of an orbital Starship upper stage at the launch site. It is a historic step towards SpaceX's goal of a fully reusable rocket.\n\nHowever, the plan to recover both stages did not fully succeed. Shortly after separation, the Super Heavy V3 booster suffered a malfunction, and an automatic abort diverted it towards the Gulf of Mexico, where it exploded as it came down into the sea. It was the first attempt to catch a V3 booster at the tower. NASA has provided around 3.2 billion dollars to turn the Ship into a lunar lander for crewed Moon missions, including Artemis III, planned for the summer of 2027."},
  {id:14, cat:"sport", title:"FIBA 3x3 Зайсан: Амстердам Дэчинг 21:15-аар хожиж, улирлын гурав дахь цолоо хүртлээ", titleEn:"FIBA 3x3 Zaisan: Amsterdam beat DeQing 21-15 for third title of the season", time:"30 мин", timeEn:"30 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/AG%2023%203x3%20Basketball%2015.jpg?width=760", text:"FIBA 3x3 Дэлхийн цуврал тэмцээний Зайсан дахь гараа өчигдөр буюу арваннэгдүгээр сарын 15-нд өндөрлөж, Нидерландын Амстердам RABOBANK баг Хятадын Дэчин багийг 21:15-аар хожиж, аварга боллоо. Тэмцээн Улаанбаатар хотын Чингис хааны өргөн чөлөөнд байрлах “Крокус” арга хэмжээний танхимд хоёр өдөр үргэлжилсэн бөгөөд 16 баг аваргын төлөө өрсөлдсөн юм.\n\nТэмцээний хамгийн үнэ цэнтэй тоглогчоор Амстердамын Ворди де Йонг тодорлоо. Тэрбээр тэмцээнд нийт 38 оноо авч, бүх тоглогчдоос хоёрдугаарт жагссан бөгөөд хасагдах шатанд онцгойрч тоглосон юм. Де Йонг Баскетс Бонн багийн эсрэг шөвгийн наймын тоглолтод болон Дэчин багийн эсрэг шигшээд тус бүр 10 оноо авч, шигшээ тоглолтыг ялалтад хүргэсэн хоёр онооны шидэлтийг гүйцэтгэсэн байна. Энэ нь Амстердам RABOBANK багийн 2026 оны улиралд хүртсэн гурав дахь Дэлхийн цувралын аварга цол юм.\n\nДэчин баг шөвгийн наймд Шанхай багийг 21:20-оор, хагас шигшээд талбайн эзэн Улаанбаатар MMC Energy багийг 22:14-өөр хожиж, шигшээд шалгарсан байна. Эцсийн дүнгээр Амстердам нэгдүгээр, Дэчин хоёрдугаар, Лиман гуравдугаар, Улаанбаатар MMC Energy дөрөвдүгээр байрт шалгарлаа. Талбайн эзэн Улаанбаатар баг Лиман багт 21:18-аар хожигдож эхэлсэн ч Торонтог 20:15-аар хожиж, хэсгээсээ шалгарсан юм. Дэлхийн цувралын дараагийн гараа арваннэгдүгээр сарын 20-21-нд Бахрейны Манама хотод болно.", textEn:"The FIBA 3x3 World Tour stop in Zaisan ended yesterday, November 15, with Amsterdam RABOBANK of the Netherlands beating DeQing of China 21-15 to take the title. The tournament ran for two days at Crocus Events Hall on Chinggis Khan Avenue in Ulaanbaatar, with 16 teams competing for the title.\n\nAmsterdam's Worthy de Jong was named the tournament's Most Valuable Player. He scored 38 points in total, ranking second among all players, and starred in the knockout stage. De Jong scored 10 points in the quarter-final against Baskets Bonn and 10 in the final against DeQing, including the title-clinching two-pointer. It is Amsterdam RABOBANK's third World Tour stop title of the 2026 season.\n\nDeQing reached the final by beating Shanghai 21-20 in the quarter-final and home favourites Ulaanbaatar MMC Energy 22-14 in the semi-final. The final standings were Amsterdam first, DeQing second, Liman third and Ulaanbaatar MMC Energy fourth. The home side lost their opener 21-18 to Liman but beat Toronto 20-15 to advance from the pool. The World Tour continues with the next stop in Manama, Bahrain, on November 20-21."},
  {id:15, cat:"sport", title:"Э.Цэндбаатар 16 дахь дараалсан ялалтаа байгуулж, WBC-гийн АНУ-ын аваргын бүс хүртлээ", titleEn:"E. Tsendbaatar claims 16th straight win and WBC USA title", time:"45 мин", timeEn:"45 min", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Boxing%20ring%20at%20AIS%20-%20Australian%20Institute%20of%20Sport.jpg?width=760", text:"Монголын мэргэжлийн боксчин, Монгол Улсын гавьяат тамирчин Эрдэнэбатын Цэндбаатар 16 дахь дараалсан ялалтаа байгуулж, WBC-гийн АНУ-ын аваргын бүсийг хүртлээ. Тэрбээр арваннэгдүгээр сарын 13-ны орой АНУ-ын Техас мужийн Эль Пасо хотын County Coliseum танхимд болсон тулаанд Тажикистаны Мухаммадхужа Якубовыг 10 раундын турш илт давуу тоглож, шүүгчдийн саналаар 98:91, 98:91, 99:90-ээр ялсан байна.\n\nЦэндбаатар тулааны эхний раундад Якубовыг баруун гартаа цохиж унагасан бөгөөд үүний дараа тулааныг бүрэн хянаж, ялалтаа баталгаажуулсан юм. Энэ ялалтаар тэрбээр мэргэжлийн бокст 16 ялалт, 0 ялагдалтай болж, WBC USA буюу АНУ-ын супер хөнгөн жингийн (130 фунт, 58.976 кг) аваргын бүсийг хүртлээ. Якубовын хувьд 23 ялалт, 2 ялагдал, 1 тэнцээтэй байсан бөгөөд WBC-гийн чансаагаар долоодугаарт жагсдаг, алдарт дасгалжуулагч Фредди Роачийн удирдлага дор Лос-Анжелес дахь Wild Card боксын клубт бэлтгэл хийдэг боксчин юм.\n\nЦэндбаатар нь хоёр удаагийн олимпод оролцсон тамирчин бөгөөд сонирхогчдын бокст 147 ялалт, 41 ялагдалтай, Монголын 11 удаагийн аварга, 2018 оны Азийн наадмын аварга, 2019 оны дэлхийн аваргын хүрэл медальт юм. Тэрбээр энэ оны тавдугаар сард Кобиа Бридиг ялж, WBC-гийн мөнгөн бүсийг хүртсэн бөгөөд дэлхийн аваргын төлөөх тулаанд улам ойртож байна.", textEn:"Mongolian professional boxer and Honored Athlete of Mongolia Tsendbaatar Erdenebat claimed his 16th consecutive victory and won the WBC USA championship belt. On the evening of November 13 at the County Coliseum in El Paso, Texas, he dominated Tajikistan's Muhammadkhuja Yaqubov over 10 rounds, winning by unanimous decision with scores of 98-91, 98-91 and 99-90.\n\nTsendbaatar dropped Yaqubov with a right hand in the opening round and controlled the fight from then on to secure the win. The victory takes his professional record to 16 wins and no defeats, and earns him the WBC USA super featherweight title (130 lbs, 58.976 kg). Yaqubov, who came into the fight with 23 wins, 2 defeats and 1 draw, is ranked seventh by the WBC and trains under renowned coach Freddie Roach at the Wild Card Boxing Club in Los Angeles.\n\nTsendbaatar is a two-time Olympian with an amateur record of 147 wins and 41 defeats, an 11-time Mongolian national champion, 2018 Asian Games gold medallist and 2019 World Championships bronze medallist. In May this year he beat Cobia Breedy to win the WBC Silver belt, and he is moving ever closer to a world title fight."},
  {id:16, cat:"sport", title:"Энэтхэг Шинэ Зеландыг 22 оноогоор хожиж, нэг өдрийн цувралыг 4:1-ээр өндөрлөлөө", titleEn:"India beat New Zealand by 22 runs to seal ODI series 4-1", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Ekana%20cricket%20stadium%20.jpg?width=760", text:"Энэтхэгийн крикетийн шигшээ баг Шинэ Зеландын Маунт Маунгануй хотод болсон тав дахь нэг өдрийн тоглолтод талбайн эздийг 22 оноогоор хожиж, цувралыг 4:1-ээр ялалтаар өндөрлөлөө. Энэтхэг Шинэ Зеландыг 187 оноонд бүгдийг нь гаргаж, цувралын ялалтаа баталгаажуулсан байна.\n\nЭнэтхэг дөрөв дэх тоглолтод Тауранга хотод ялж, цувралд 3:1-ээр тэргүүлсэн байсан бөгөөд тав дахь тоглолтын ялалтаар цувралын ялалтаа бататгасан юм. Энэ нь Энэтхэгийн Шинэ Зеланд дахь сүүлийн долоон жилийн анхны нэг өдрийн цувралын ялалт болж байна. Тав дахь тоглолтод Энэтхэгийн бөмбөгчид талбайн эздийн цохигчдыг тогтмол шахаж, 187 оноонд бүгдийг нь гаргасан нь ялалтын үндэс болсон байна.\n\nЦувралын ялалт нь Энэтхэгийн крикетийн хувьд чухал амжилт болж байна. Шинэ Зеландын талбайд ялалт байгуулах нь зочин багийн хувьд үргэлж хүнд сорилт байдаг бөгөөд Энэтхэг энэ удаагийн цувралд илт давуу тоглосон юм.", textEn:"India's cricket team beat hosts New Zealand by 22 runs in the fifth one-day international in Mount Maunganui, sealing the series 4-1. India bowled New Zealand out for 187 to confirm the series win.\n\nIndia had already taken a 3-1 lead with victory in the fourth match in Tauranga, and the win in the fifth match confirmed the series triumph. It is India's first one-day series win in New Zealand in seven years. In the fifth match, India's bowlers kept constant pressure on the home batsmen, dismissing them all for 187, which proved the foundation of the win.\n\nThe series victory is an important achievement for Indian cricket. Winning in New Zealand is always a difficult challenge for a visiting team, and India were clearly the better side in this series."},
  {id:17, cat:"soyol", title:"Melon Music Awards 2026: BTS, IVE, CORTIS нар их шагналыг хүртлээ", titleEn:"Melon Music Awards 2026: BTS, IVE and CORTIS take the grand prizes", time:"1 цаг", timeEn:"1 hour", img:"https://commons.wikimedia.org/wiki/Special:FilePath/IVE%20%28%EC%95%84%EC%9D%B4%EB%B8%8C%29%20performing%20at%20the%202023%20World%20Scout%20Jamboree%20K-POP%20Super%20Live%20Concert.jpg?width=760", text:"Солонгосын хөгжмийн нэр хүндтэй шагнал болох 18 дахь удаагийн Melon Music Awards арваннэгдүгээр сарын 14-15-нд Сөүл хотын Гочеок Скай Домд болж, хоёр өдрийн турш үргэлжилсэн анхны ёслол боллоо. Хоёр дахь өдөр буюу арваннэгдүгээр сарын 15-нд үлдсэн гурван их шагналыг зарласан бөгөөд BTS “Оны шилдэг уран бүтээлч”, IVE “BANG BANG” дуугаараа “Оны шилдэг дуу”, CORTIS “Оны шилдэг цомог” шагналыг тус тус хүртлээ.\n\nBTS нь энэ удаагийн ёслолд нийт зургаан шагнал хүртэж, хамгийн олон шагнал авсан уран бүтээлч боллоо. Тэд эхний өдөр “Arirang” цомгоороо “Оны шилдэг цомог” шагналыг хүртсэн бөгөөд хоёр дахь өдөр “Оны шилдэг уран бүтээлч” болон “Шилдэг эрэгтэй хамтлаг” шагналыг нэмж авсан байна. IVE нь “Оны шилдэг дуу”, “Шилдэг эмэгтэй хамтлаг”, “Шилдэг хөгжмийн видео” зэрэг таван шагнал хүртэж, хоёрдугаарт жагслаа.\n\nIVE хоёр дахь өдрийн ёслолд дебют үеийнхээ дуунуудыг шинэ найруулгаар дуулсан тусгай тоглолт хийсэн нь үзэгчдийн анхаарлыг татсан юм. Ёслолд ILLIT, NCT WISH, PLAVE, KiiiKiii, NCT 127 зэрэг 12 хамтлаг оролцсон байна. Melon Music Awards нь Melon платформын дамжуулалтын мэдээлэл, хэрэглэгчдийн санал болон шинжээчдийн үнэлгээгээр шагналыг олгодог. IVE-ийн хамгийн сүүлийн мини цомог “Looks Can Kill” нь АНУ-ын Billboard 200 чартад анх удаа орсон нь тус хамтлагийн хувьд шинэ амжилт болж байна.", textEn:"The 18th Melon Music Awards, one of South Korea's most prestigious music awards, took place on November 14-15 at the Gocheok Sky Dome in Seoul, running over two days for the first time. On the second day, November 15, the remaining three grand prizes were announced: BTS won Artist of the Year, IVE won Song of the Year for \"BANG BANG\", and CORTIS won Record of the Year.\n\nBTS took home six awards in total, the most of any artist at this year's ceremony. They won Album of the Year for \"Arirang\" on the first day, adding Artist of the Year and Best Male Group on the second day. IVE followed with five awards, including Song of the Year, Best Female Group and Best Music Video.\n\nIVE also performed a special stage on the second day, singing songs from their debut era in new arrangements, which drew the audience's attention. Twelve acts took part in the ceremony, including ILLIT, NCT WISH, PLAVE, KiiiKiii and NCT 127. The Melon Music Awards are decided using Melon streaming data, user voting and expert evaluation. IVE's latest mini album, \"Looks Can Kill\", entered the US Billboard 200 for the first time, a new milestone for the group."},
  {id:18, cat:"soyol", title:"Хүннүгийн хамгийн том булшнаас 413 олдвор илэрлээ: Ромын шилэн сав байж болзошгүй эд гарчээ", titleEn:"413 artifacts found in largest Xiongnu tomb, including possible Roman glass vessel", time:"2 цаг", timeEn:"2 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Han%20Xiongnu%20Gold%20Hair%20Ornament%20%2810336818014%29.jpg?width=760", text:"Монголын зүүн нутаг дахь Дуурлиг Нарс оршуулгын газарт байрлах Хүннүгийн эзэнт гүрний үеийн сүрлэг булшнаас нийт 413 олдвор илэрсэн тухай археологичид мэдээллээ. Уг булш нь 73 метр орчим урт бөгөөд олдворуудын дунд Ромын шилэн сав байж болзошгүй эд зүйл, хаш чулуу, Солонгосын чимэглэл болон онцгой алтан эдлэл багтсан байна.\n\nСудалгааг Солонгосын Үндэсний музей, Монголын Шинжлэх ухааны академи, Монголын Үндэсний музейн мэргэжилтнүүд хамтран хийсэн байна. 413 олдвор нь Хүннүгийн элитүүд Евразийн өргөн уудам нутаг дахь худалдааны сүлжээнд хэрхэн холбогдож байсныг харуулж байгаа бөгөөд эртний нүүдэлчид болон Ромын эзэнт гүрэн, Хятад, Солонгосын хойг хоорондын холбоог гэрчилж байна.\n\nХүннүгийн эзэнт гүрэн нь МЭӨ III зуунаас МЭ I зуун хүртэл Төв Азийн тал нутагт оршин тогтнож, Торгоны замын худалдаанд чухал үүрэг гүйцэтгэж байсан юм. Дуурлиг Нарс оршуулгын газар нь Хүннүгийн язгууртнуудын оршуулгын газруудын нэг бөгөөд өмнө нь ч чухал олдворууд олдсон байна. Олдворуудыг цаашид судалж, хадгалж, олон нийтэд үзүүлэхээр төлөвлөж байна.", textEn:"Archaeologists have reported that a total of 413 artifacts have been found in a monumental tomb of the Xiongnu Empire at the Duurlig Nars cemetery in eastern Mongolia. The tomb is approximately 73 metres long, and the finds include an object believed to be a Roman glass vessel, jade, a Korean ornament and distinctive gold artifacts.\n\nThe research was conducted by specialists from the National Museum of Korea, the Mongolian Academy of Sciences and the National Museum of Mongolia. The 413 artifacts show how the Xiongnu elite were connected to trade networks across Eurasia, bearing witness to links between the ancient nomads and the Roman Empire, China and the Korean Peninsula.\n\nThe Xiongnu Empire dominated the Central Asian steppe from the 3rd century BCE to the 1st century CE and played an important role in Silk Road trade. The Duurlig Nars cemetery is one of the burial grounds of Xiongnu nobility, where important finds have been made before. The artifacts will be further studied, preserved and presented to the public."},
  {id:19, cat:"oron-nutag", title:"ЗАВХАН: Цас 30 см хүрч, Тэс сумын хээрийн замаар машин явах боломжгүй боллоо", titleEn:"ZAVKHAN: Snow reaches 30 cm, steppe road in Tes soum impassable", time:"3 цаг", timeEn:"3 hours", img:"https://commons.wikimedia.org/wiki/Special:FilePath/Mongolia%20Winter%20%28127750833%29.jpeg?width=760", text:"Завхан аймагт цас 30 сантиметр хүрч, Тэс сумын хээрийн замаар машин явах боломжгүй болсон тухай мэдээллээ. Арваннэгдүгээр сарын 15-16-нд шилжих шөнө Завхан, Говь-Алтай, Баянхонгор, Өвөрхангайн ихэнх нутгаар цас орж, цасан шуурга шуурсан бөгөөд Завхан аймагт цас хамгийн их орсон газруудын нэг боллоо.\n\nТэс сум нь Завхан аймгийн баруун хойд хэсэгт орших бөгөөд сумын төвөөс гарах хээрийн замд цас зузаан хучсан тул тээврийн хэрэгсэл зорчих боломжгүй болсон байна. Малчид, иргэд, тээвэрчид зам, даваа, гүвээнд үзэгдэх орчин хязгаарлагдаж, халтиргаа гулгаа, мөстөлт үүсэхийг анхаарч, хол замд гарахдаа бэлтгэлтэй байхыг цаг уурын байгууллагаас анхааруулж байна.\n\nЦаг уурын байгууллагын мэдээлснээр арваннэгдүгээр сарын 16-ны өдөр Завхан, Хөвсгөлийн зүүн, Говь-Алтай, Баянхонгор, Дундговийн хойд, Архангай, Өвөрхангай, Булган, Сэлэнгэ, Төв аймгийн ихэнх сумдын нутгаар цас орж, цасан шуурга шуурах төлөвтэй байна. Салхи нутгийн зарим газраар секундэд 15-17 метр хүрч ширүүсч, ихэнх нутгаар хүйтрэх төлөвтэй байна.", textEn:"Snow has reached 30 centimetres in Zavkhan aimag, and vehicles can no longer travel on the steppe road in Tes soum. On the night of November 15-16, snow and blizzards covered most of Zavkhan, Govi-Altai, Bayankhongor and Uvurkhangai, with Zavkhan among the places receiving the heaviest snow.\n\nTes soum lies in the north-western part of Zavkhan aimag, and the steppe road out of the soum centre is covered in thick snow, making it impassable for vehicles. Herders, residents and drivers are warned that visibility is limited on roads, passes and hills, with slippery conditions and icing, and are advised to prepare carefully before long journeys.\n\nAccording to the weather agency, snow and blizzards are expected on November 16 across most of Zavkhan, eastern Khuvsgul, Govi-Altai, Bayankhongor, northern Dundgovi, Arkhangai, Uvurkhangai, Bulgan, Selenge and Tuv. Winds will strengthen to 15-17 metres per second in parts of the country, and temperatures will fall across most areas.", region:"zavkhan"},
];

function aTitle(a){ return LANG === "en" ? (a.titleEn || a.title) : a.title; }
function aTime(a){ return LANG === "en" ? (a.timeEn || a.time) : a.time; }
function aText(a){ if(a.text) return LANG === "en" ? (a.textEn || a.text) : a.text; return SAMPLE_TEXT[LANG][a.id === 1 ? "long" : "short"]; }
function aRegion(a){ return a.region ? ((REGIONS[LANG] && REGIONS[LANG][a.region]) || a.region) : ""; }

// ===== Ханш · Цаг агаар (өдөр бүр шинэчлэгдэнэ; цаг агаарыг Open-Meteo-гоос шууд татна) =====
const RATES = {date:"2026-11-15", items:[
  {code:"USD", mnt:3603.46, chg:0}, {code:"EUR", mnt:3985.43, chg:0}, {code:"JPY", mnt:22.54, chg:0},
  {code:"CNY", mnt:540.2, chg:0}, {code:"KRW", mnt:2.69, chg:0}, {code:"RUB", mnt:43.79, chg:0}, {code:"GBP", mnt:4767.2, chg:0}
]};
let WEATHER = [
  {city:"Улаанбаатар", cityEn:"Ulaanbaatar", lat:47.9212, lon:106.9186, tz:"Asia/Ulaanbaatar", temp:-11, code:71},
  {city:"Токио", cityEn:"Tokyo", lat:35.6762, lon:139.6503, tz:"Asia/Tokyo", temp:19, code:0},
  {city:"Сөүл", cityEn:"Seoul", lat:37.5665, lon:126.978, tz:"Asia/Seoul", temp:8, code:3},
  {city:"Бээжин", cityEn:"Beijing", lat:39.9042, lon:116.4074, tz:"Asia/Shanghai", temp:6, code:61},
  {city:"Москва", cityEn:"Moscow", lat:55.7558, lon:37.6173, tz:"Europe/Moscow", temp:3, code:3}
];
function wIcon(code){
  if(code === 0) return "☀️";
  if(code === 1) return "🌤️";
  if(code === 2) return "⛅";
  if(code === 3) return "☁️";
  if(code === 45 || code === 48) return "🌫️";
  if(code === 51 || code === 53 || code === 55 || code === 80) return "🌦️";
  if(code === 56 || code === 57 || code === 61 || code === 63 || code === 65 || code === 66 || code === 67 || code === 81 || code === 82) return "🌧️";
  if(code === 71 || code === 73 || code === 75 || code === 77 || code === 85 || code === 86) return "❄️";
  if(code >= 95) return "⛈️";
  return "🌡️";
}
function fmtRate(v){
  if(v >= 100) return Math.round(v).toLocaleString("en-US");
  return v.toFixed(2);
}
function renderData(){
  const parts = [];
  RATES.items.forEach(r=>{
    let arrow = "";
    if(r.chg > 0) arrow = ' <span class="up">▲</span>';
    else if(r.chg < 0) arrow = ' <span class="down">▼</span>';
    parts.push(`<span class="tk"><b>${r.code}</b> ${fmtRate(r.mnt)}₮${arrow}</span>`);
  });
  WEATHER.forEach(w=>{
    const name = LANG === "en" ? w.cityEn : w.city;
    const t = w.temp > 0 ? "+" + w.temp : "" + w.temp;
    parts.push(`<span class="tk">${wIcon(w.code)} ${name} ${t}°C</span>`);
  });
  const html = parts.join('<span style="color:#666">•</span>');
  const track = document.getElementById("tickerTrack");
  if(track) track.innerHTML = html + '<span style="color:#666">•</span>' + html + '<span style="color:#666">•</span>';
  const usd = RATES.items.find(r=>r.code === "USD");
  const ue = document.getElementById("usdText");
  if(ue && usd) ue.textContent = "USD: " + fmtRate(usd.mnt) + "₮";
  const wt = document.getElementById("weatherText");
  const ub = WEATHER[0];
  if(wt && ub) wt.textContent = wIcon(ub.code) + " " + (LANG === "en" ? ub.cityEn : ub.city) + " " + (ub.temp > 0 ? "+" + ub.temp : ub.temp) + "°C";
}
function refreshWeather(){
  WEATHER.forEach((w, idx)=>{
    const url = "https://api.open-meteo.com/v1/forecast?latitude=" + w.lat + "&longitude=" + w.lon + "&current=temperature_2m%2Cweather_code&timezone=" + encodeURIComponent(w.tz);
    fetch(url).then(r=>r.json()).then(d=>{
      if(d && d.current){ WEATHER[idx].temp = Math.round(d.current.temperature_2m); WEATHER[idx].code = d.current.weather_code; renderData(); }
    }).catch(()=>{});
  });
}

